from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
import hashlib, json, re

root = Path('products/distribution/sqlite-lemonsqueezy-fit')
policy_link = re.compile(r'payout|get(?:ting)?[- ]paid|onboard|activat|verif|bank|paypal|identity', re.I)

class Links(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.active = None
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.active = (dict(attrs).get('href') or '', [])

    def handle_data(self, text):
        if self.active is not None:
            self.active[1].append(text)

    def handle_endtag(self, tag):
        if tag == 'a' and self.active is not None:
            href, parts = self.active
            self.links.append((href, ' '.join(' '.join(parts).split())))
            self.active = None

sources = []
for name in ('fees', 'prohibited-products', 'supported-countries'):
    source = f'https://docs.lemonsqueezy.com/help/getting-started/{name}'
    raw = (root / 'raw' / f'{name}.html').read_bytes()
    parser = Links()
    parser.feed(raw.decode('utf-8', errors='replace'))
    links = {}
    for href, label in parser.links:
        target = urlsplit(urljoin(source, href))
        if target.scheme != 'https' or target.netloc != 'docs.lemonsqueezy.com' or not target.path.startswith('/help/'):
            continue
        if target.path == urlsplit(source).path or not policy_link.search(target.path + ' ' + label):
            continue
        url = target._replace(query='', fragment='').geturl()
        links.setdefault(url, label)
    sources.append({'source': source, 'sha256': hashlib.sha256(raw).hexdigest(), 'links': [{'url': url, 'label': label} for url, label in sorted(links.items())]})
result = {'scope': 'Links extracted from three committed first-party captures. Destination content and seller eligibility remain unverified.', 'sources': sources}
path = root / 'director-onboarding-policy-links.json'
path.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
assert json.loads(path.read_text(encoding='utf-8')) == result
print(json.dumps({'artifact': str(path), 'distinct_policy_links': len({link['url'] for row in sources for link in row['links']})}))
